"""Newly authored practice papers 01/02 for Dekiru lessons 6–7.

Lexical targets follow data/vocabulary.js, source PDF pages 18–23.
The 45-question category matrix follows material-adapted-01.
"""

from exam67_common import q


LEX_RULES = {
    'reading': 'Đọc đúng cả mục từ; chú ý trường âm, âm ghép và âm đục. Không ghép tùy ý âm của từng chữ Hán.',
    'spelling': 'Đối chiếu đồng thời cách đọc và nghĩa được yêu cầu. Chữ có hình hoặc âm gần nhau không tự thay thế nhau.',
    'vocabulary': 'Chọn nghĩa của mục từ trong tình huống cụ thể; phân biệt người thực hiện và hướng của hành động.',
}


def _questions(source):
    result = []
    for line in source.strip().splitlines():
        fields = line.split('|')
        assert len(fields) == 15, fields
        category, lesson, topic, unit, prompt, a, b, c, d, completed, meaning, why, rb, rc, rd = fields
        result.append(q(category, int(lesson), int(topic), unit, prompt, a, [b, c, d], completed, meaning, why, [rb, rc, rd], rule=LEX_RULES.get(category)))
    return result


